import{_ as s,o as n,c as p,a2 as e}from"./chunks/framework.DYYBR_aZ.js";const u=JSON.parse('{"title":"Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j","description":"","frontmatter":{},"headers":[],"relativePath":"java/Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j.md","filePath":"java/Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j.md"}'),i={name:"java/Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j.md"};function t(l,a,o,r,c,d){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="spring-boot-接口文档实践-swagger、openapi-与-knife4j" tabindex="-1">Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j <a class="header-anchor" href="#spring-boot-接口文档实践-swagger、openapi-与-knife4j" aria-label="Permalink to &quot;Spring Boot 接口文档实践：Swagger、OpenAPI 与 Knife4j&quot;">​</a></h1><h2 id="一、为什么需要接口文档" tabindex="-1">一、为什么需要接口文档？ <a class="header-anchor" href="#一、为什么需要接口文档" aria-label="Permalink to &quot;一、为什么需要接口文档？&quot;">​</a></h2><p>在实际 Java 后端开发中，Controller 提供了大量 HTTP 接口。如果没有统一的接口文档，前后端开发人员、测试人员以及其他服务的开发人员，就需要反复查看 Controller 源码，才能知道接口的请求地址、请求方式、参数格式和返回结构。</p><p>例如：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Operation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">summary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;商家创建优惠券推送任务&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NoDuplicateSubmit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">message</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;请勿短时间内重复提交优惠券推送任务&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PostMapping</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/api/merchant-admin/coupon-task/create&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> createCouponTask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        @</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">RequestBody</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CouponTaskCreateReqDTO requestParam) {</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    couponTaskService.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">createCouponTask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(requestParam);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Results.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>如果没有接口文档，调用方需要自己确认：</p><ul><li>请求方式是 POST 还是 GET？</li><li>请求地址是什么？</li><li>请求体需要传递哪些字段？</li><li>哪些参数是必填的？</li><li>返回结果是什么结构？</li><li>接口有哪些业务限制？</li></ul><p>Swagger、OpenAPI 和 Knife4j 正是为了解决这类问题而存在的。</p><h2 id="二、先理解三个核心概念" tabindex="-1">二、先理解三个核心概念 <a class="header-anchor" href="#二、先理解三个核心概念" aria-label="Permalink to &quot;二、先理解三个核心概念&quot;">​</a></h2><h3 id="_1-openapi-接口描述规范" tabindex="-1">1. OpenAPI：接口描述规范 <a class="header-anchor" href="#_1-openapi-接口描述规范" aria-label="Permalink to &quot;1. OpenAPI：接口描述规范&quot;">​</a></h3><p>OpenAPI 是一种用于描述 HTTP API 的标准规范。</p><p>它规定了如何使用结构化数据描述一个接口，包括：</p><ul><li>接口路径和请求方式；</li><li>请求参数及参数类型；</li><li>请求体结构；</li><li>响应数据结构；</li><li>接口说明及标签；</li><li>请求和响应的状态码。</li></ul><p>例如，一个接口可以被描述为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/api/merchant-admin/coupon-task/create:</span></span>
<span class="line"><span>  post:</span></span>
<span class="line"><span>    summary: 商家创建优惠券推送任务</span></span>
<span class="line"><span>    requestBody:</span></span>
<span class="line"><span>      required: true</span></span>
<span class="line"><span>      content:</span></span>
<span class="line"><span>        application/json:</span></span>
<span class="line"><span>          schema:</span></span>
<span class="line"><span>            type: object</span></span>
<span class="line"><span>    responses:</span></span>
<span class="line"><span>      &#39;200&#39;:</span></span>
<span class="line"><span>        description: 请求成功</span></span></code></pre></div><p>这是一种机器可读的接口描述方式。</p><p>需要注意：OpenAPI 本身不是一个接口开发框架，也不负责处理 HTTP 请求。它只是定义了一套描述 API 的规范。</p><p>可以把它理解为：<strong>后端开发人员和接口调用方共同遵守的接口说明书格式。</strong></p><h3 id="_2-swagger-围绕-api-规范的工具生态" tabindex="-1">2. Swagger：围绕 API 规范的工具生态 <a class="header-anchor" href="#_2-swagger-围绕-api-规范的工具生态" aria-label="Permalink to &quot;2. Swagger：围绕 API 规范的工具生态&quot;">​</a></h3><p>Swagger 是一套与 API 设计、描述和调试相关的工具生态。</p><p>常见工具包括：</p><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td>Swagger UI</td><td>将 OpenAPI 文档渲染为可交互的网页</td></tr><tr><td>Swagger Editor</td><td>编写和编辑 API 规范</td></tr><tr><td>Swagger Codegen</td><td>根据 API 描述生成客户端或服务端代码</td></tr></tbody></table><p>这里还需要了解一个历史背景：</p><p>早期 Swagger 规范后来被捐赠并演进为 OpenAPI 规范。Swagger 这个名称则继续用于相关工具生态。</p><p>所以现在我们经常看到：</p><ul><li>Swagger 2.0：旧版 API 描述规范；</li><li>OpenAPI 3.x：新版 API 描述规范；</li><li>Swagger UI：可以读取 OpenAPI 文档并展示接口的工具。</li></ul><h3 id="_3-knife4j-面向-java-开发的接口文档增强工具" tabindex="-1">3. Knife4j：面向 Java 开发的接口文档增强工具 <a class="header-anchor" href="#_3-knife4j-面向-java-开发的接口文档增强工具" aria-label="Permalink to &quot;3. Knife4j：面向 Java 开发的接口文档增强工具&quot;">​</a></h3><p>Knife4j 是 Java 生态中常见的接口文档工具，提供接口文档展示、调试、搜索、分组等增强能力。</p><p>在 Spring Boot 项目中，Knife4j 通常与 Springdoc-OpenAPI 配合使用。</p><p>其中：</p><ul><li>Springdoc-OpenAPI：负责扫描 Spring Boot 应用中的接口信息，生成 OpenAPI 文档。</li><li>Knife4j：提供增强的接口文档展示和调试体验。</li></ul><p>因此，Knife4j 并不是另一套与 OpenAPI 无关的接口描述规范，而是建立在 OpenAPI 体系之上的工具。</p><h2 id="三、这几个工具之间是什么关系" tabindex="-1">三、这几个工具之间是什么关系？ <a class="header-anchor" href="#三、这几个工具之间是什么关系" aria-label="Permalink to &quot;三、这几个工具之间是什么关系？&quot;">​</a></h2><p>先看整体架构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>            Spring Boot 项目</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>                   v</span></span>
<span class="line"><span>             Controller</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>          Spring MVC 接口映射</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>                   v</span></span>
<span class="line"><span>          Springdoc-OpenAPI</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>       扫描 Controller、DTO、</span></span>
<span class="line"><span>       Spring 注解和 OpenAPI 注解</span></span>
<span class="line"><span>                   |</span></span>
<span class="line"><span>                   v</span></span>
<span class="line"><span>             OpenAPI JSON</span></span>
<span class="line"><span>              /         \\</span></span>
<span class="line"><span>             /           \\</span></span>
<span class="line"><span>            v             v</span></span>
<span class="line"><span>       Swagger UI       Knife4j</span></span>
<span class="line"><span>            |             |</span></span>
<span class="line"><span>            v             v</span></span>
<span class="line"><span>       接口文档展示     增强文档展示</span></span>
<span class="line"><span>       和接口调试       和接口调试</span></span></code></pre></div><p>这里最重要的是：</p><p><strong>后端接口只需要按照正常的 Spring MVC 方式开发，文档框架就可以根据接口映射和注解信息自动生成 OpenAPI 描述。</strong></p><p>我们不需要为每个 Controller 手工编写一份独立的接口文档。</p><h2 id="四、spring-boot-是如何自动生成接口文档的" tabindex="-1">四、Spring Boot 是如何自动生成接口文档的？ <a class="header-anchor" href="#四、spring-boot-是如何自动生成接口文档的" aria-label="Permalink to &quot;四、Spring Boot 是如何自动生成接口文档的？&quot;">​</a></h2><p>这是最值得理解的部分。</p><h3 id="_1-引入相关依赖" tabindex="-1">1. 引入相关依赖 <a class="header-anchor" href="#_1-引入相关依赖" aria-label="Permalink to &quot;1. 引入相关依赖&quot;">​</a></h3><p><strong>在 Maven 项目中引入 Knife4j 对应的 Starter。</strong></p><p>例如，Spring Boot 3 的 OpenAPI 3 集成可以使用：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>    &lt;groupId&gt;com.github.xiaoymin&lt;/groupId&gt;</span></span>
<span class="line"><span>    &lt;artifactId&gt;knife4j-openapi3-jakarta-spring-boot-starter&lt;/artifactId&gt;</span></span>
<span class="line"><span>    &lt;version&gt;对应兼容版本&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><p>这个 Starter 会引入相应的 OpenAPI 文档生成和展示组件。</p><p>项目启动时，Spring Boot 会根据依赖中的自动配置机制注册相关组件。</p><p>因此，我们不需要自己编写一个 Controller 来实现 <code>/v3/api-docs</code>。</p><p>注意：实际使用时必须根据 Spring Boot、JDK 和 Knife4j 版本选择兼容的依赖。Spring Boot 2 的项目也有对应集成方式。</p><h3 id="_2-springdoc-扫描-controller" tabindex="-1">2. Springdoc 扫描 Controller <a class="header-anchor" href="#_2-springdoc-扫描-controller" aria-label="Permalink to &quot;2. Springdoc 扫描 Controller&quot;">​</a></h3><p>假设我们有下面的接口：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@RestController</span></span>
<span class="line"><span>@RequestMapping(&quot;/api/coupon&quot;)</span></span>
<span class="line"><span>@Tag(name = &quot;优惠券管理&quot;)</span></span>
<span class="line"><span>public class CouponController {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Operation(summary = &quot;根据 ID 查询优惠券&quot;)</span></span>
<span class="line"><span>    @GetMapping(&quot;/{id}&quot;)</span></span>
<span class="line"><span>    public Result&lt;CouponDTO&gt; findCoupon(</span></span>
<span class="line"><span>            @PathVariable Long id) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        return Results.success(</span></span>
<span class="line"><span>                couponService.findById(id)</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Springdoc 会结合 Spring MVC 的接口映射信息和 OpenAPI 注解，分析这个 Controller。</p><p>它能够识别：</p><table tabindex="0"><thead><tr><th>代码</th><th>文档中的含义</th></tr></thead><tbody><tr><td><code>@RestController</code></td><td>REST 控制器</td></tr><tr><td><code>@RequestMapping</code></td><td>接口公共路径</td></tr><tr><td><code>@GetMapping</code></td><td>HTTP GET 请求</td></tr><tr><td><code>@PathVariable</code></td><td>URL 路径参数</td></tr><tr><td><code>@Tag</code></td><td>接口分组</td></tr><tr><td><code>@Operation</code></td><td>接口说明</td></tr><tr><td><code>Result</code></td><td>响应数据结构</td></tr></tbody></table><p>最终形成对应的 OpenAPI 描述。</p><p>这里需要注意：Spring MVC 注解决定实际接口的路由和参数绑定，而 OpenAPI 注解主要用于补充接口文档的描述信息。</p><h3 id="_3-dto-也会参与文档生成" tabindex="-1">3. DTO 也会参与文档生成 <a class="header-anchor" href="#_3-dto-也会参与文档生成" aria-label="Permalink to &quot;3. DTO 也会参与文档生成&quot;">​</a></h3><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Data</span></span>
<span class="line"><span>public class CouponCreateReqDTO {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Schema(description = &quot;优惠券名称&quot;, requiredMode = Schema.RequiredMode.REQUIRED)</span></span>
<span class="line"><span>    private String name;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Schema(description = &quot;优惠券库存&quot;)</span></span>
<span class="line"><span>    private Integer stock;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Schema(description = &quot;优惠券类型&quot;)</span></span>
<span class="line"><span>    private Integer type;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Springdoc 可以结合 DTO 的字段、类型、校验约束以及 <code>@Schema</code> 等注解生成请求参数模型。</p><p>因此，文档不仅可以展示接口地址，还可以展示请求体中有哪些字段、字段类型是什么、字段有什么业务含义。</p><h2 id="五、三个常见访问地址分别有什么作用" tabindex="-1">五、三个常见访问地址分别有什么作用？ <a class="header-anchor" href="#五、三个常见访问地址分别有什么作用" aria-label="Permalink to &quot;五、三个常见访问地址分别有什么作用？&quot;">​</a></h2><p>以我们正在运行的 oneCoupon 项目为例：</p><h3 id="_1-knife4j-doc-html" tabindex="-1">1. Knife4j：/doc.html <a class="header-anchor" href="#_1-knife4j-doc-html" aria-label="Permalink to &quot;1. Knife4j：/doc.html&quot;">​</a></h3><p>访问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:10010/doc.html</span></span></code></pre></div><p>这是我们日常使用最多的入口。</p><p>主要功能：</p><ul><li>查看接口分组；</li><li>查看接口请求方式和请求地址；</li><li>查看请求参数；</li><li>查看 DTO 字段说明；</li><li>查看响应结构；</li><li>在线调试接口；</li><li>搜索接口。</li></ul><p>它本质上是一个文档展示与调试页面。</p><h3 id="_2-swagger-ui-swagger-ui-html" tabindex="-1">2. Swagger UI：/swagger-ui.html <a class="header-anchor" href="#_2-swagger-ui-swagger-ui-html" aria-label="Permalink to &quot;2. Swagger UI：/swagger-ui.html&quot;">​</a></h3><p>访问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:10010/swagger-ui.html</span></span></code></pre></div><p>Swagger UI 同样能够读取 OpenAPI 文档并展示接口。</p><p>与 Knife4j 相比，它提供的是相对基础的接口文档展示和调试体验。</p><p>两者的定位比较接近，但前端实现和增强功能不同。</p><h3 id="_3-openapi-json-v3-api-docs" tabindex="-1">3. OpenAPI JSON：/v3/api-docs <a class="header-anchor" href="#_3-openapi-json-v3-api-docs" aria-label="Permalink to &quot;3. OpenAPI JSON：/v3/api-docs&quot;">​</a></h3><p>访问：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://127.0.0.1:10010/v3/api-docs</span></span></code></pre></div><p>这个入口非常重要。</p><p>它返回的是机器可读的 OpenAPI JSON 数据，而不是给人直接阅读的图形化文档。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{</span></span>
<span class="line"><span>  &quot;openapi&quot;: &quot;3.0.1&quot;,</span></span>
<span class="line"><span>  &quot;paths&quot;: {</span></span>
<span class="line"><span>    &quot;/api/coupon/{id}&quot;: {</span></span>
<span class="line"><span>      &quot;get&quot;: {</span></span>
<span class="line"><span>        &quot;summary&quot;: &quot;根据 ID 查询优惠券&quot;</span></span>
<span class="line"><span>      }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>实际返回内容会包含更完整的接口参数、请求体、响应结构和组件定义。</p><p>它有什么价值？</p><p><strong>第一，作为接口文档的数据源。</strong></p><p>Knife4j 和 Swagger UI 可以读取它，再将其渲染为可视化页面。</p><p><strong>第二，供第三方工具导入。</strong></p><p>例如，Apifox、Postman 等工具可以导入 OpenAPI JSON，从而自动生成接口集合，减少手工维护接口信息的工作量。</p><p><strong>第三，支持自动化开发。</strong></p><p>可以基于 OpenAPI 描述生成客户端 SDK、接口调用代码，或者用于接口契约检查。</p><p>所以，<code>/v3/api-docs</code> 是整套体系中非常重要的一个组成部分。</p><h2 id="六、常用注解及其作用" tabindex="-1">六、常用注解及其作用 <a class="header-anchor" href="#六、常用注解及其作用" aria-label="Permalink to &quot;六、常用注解及其作用&quot;">​</a></h2><p>在实际开发中，我们不需要记住所有注解，掌握以下几个就足够应付大部分业务场景。</p><h3 id="_1-tag-接口分组" tabindex="-1">1. @Tag：接口分组 <a class="header-anchor" href="#_1-tag-接口分组" aria-label="Permalink to &quot;1. @Tag：接口分组&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Tag(name = &quot;优惠券模板管理&quot;)</span></span>
<span class="line"><span>@RestController</span></span>
<span class="line"><span>public class CouponTemplateController {</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用于给 Controller 下的接口设置分组。</p><h3 id="_2-operation-接口说明" tabindex="-1">2. @Operation：接口说明 <a class="header-anchor" href="#_2-operation-接口说明" aria-label="Permalink to &quot;2. @Operation：接口说明&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Operation(summary = &quot;商家创建优惠券模板&quot;)</span></span>
<span class="line"><span>@PostMapping(&quot;/create&quot;)</span></span>
<span class="line"><span>public Result&lt;String&gt; create() {</span></span>
<span class="line"><span>    return Results.success();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用于描述接口的主要用途。</p><p>我们之前看到的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Operation(summary = &quot;商家创建优惠券推送任务&quot;)</span></span></code></pre></div><p>就是告诉接口文档，这个接口的业务含义是什么。</p><h3 id="_3-parameter-参数说明" tabindex="-1">3. @Parameter：参数说明 <a class="header-anchor" href="#_3-parameter-参数说明" aria-label="Permalink to &quot;3. @Parameter：参数说明&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Operation(summary = &quot;查询优惠券&quot;)</span></span>
<span class="line"><span>@GetMapping(&quot;/find&quot;)</span></span>
<span class="line"><span>public Result&lt;CouponDTO&gt; find(</span></span>
<span class="line"><span>        @Parameter(description = &quot;优惠券模板 ID&quot;)</span></span>
<span class="line"><span>        @RequestParam Long couponTemplateId) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    return Results.success();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用于补充参数的说明、是否必填等信息。</p><h3 id="_4-schema-dto-字段说明" tabindex="-1">4. @Schema：DTO 字段说明 <a class="header-anchor" href="#_4-schema-dto-字段说明" aria-label="Permalink to &quot;4. @Schema：DTO 字段说明&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Data</span></span>
<span class="line"><span>public class CouponCreateReqDTO {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Schema(description = &quot;优惠券名称&quot;)</span></span>
<span class="line"><span>    private String name;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    @Schema(description = &quot;优惠券库存&quot;)</span></span>
<span class="line"><span>    private Integer stock;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用于描述请求对象、响应对象及其字段。</p><h3 id="_5-apiresponse-响应说明" tabindex="-1">5. @ApiResponse：响应说明 <a class="header-anchor" href="#_5-apiresponse-响应说明" aria-label="Permalink to &quot;5. @ApiResponse：响应说明&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Operation(summary = &quot;查询优惠券&quot;)</span></span>
<span class="line"><span>@ApiResponse(</span></span>
<span class="line"><span>    responseCode = &quot;200&quot;,</span></span>
<span class="line"><span>    description = &quot;查询成功&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@GetMapping(&quot;/find&quot;)</span></span>
<span class="line"><span>public Result&lt;CouponDTO&gt; find() {</span></span>
<span class="line"><span>    return Results.success();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>用于补充不同 HTTP 状态码对应的响应说明。</p><h2 id="七、结合-onecoupon-项目实际操作" tabindex="-1">七、结合 oneCoupon 项目实际操作 <a class="header-anchor" href="#七、结合-onecoupon-项目实际操作" aria-label="Permalink to &quot;七、结合 oneCoupon 项目实际操作&quot;">​</a></h2><p>我们之前一直在学习商家创建优惠券模板、查询优惠券模板以及创建优惠券推送任务。</p><p>现在可以通过 Knife4j 把这些知识串起来。</p><p>例如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@Operation(summary = &quot;商家创建优惠券推送任务&quot;)</span></span>
<span class="line"><span>@NoDuplicateSubmit(</span></span>
<span class="line"><span>    message = &quot;请勿短时间内重复提交优惠券推送任务&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>@PostMapping(&quot;/api/merchant-admin/coupon-task/create&quot;)</span></span>
<span class="line"><span>public Result&lt;Void&gt; createCouponTask(</span></span>
<span class="line"><span>        @RequestBody CouponTaskCreateReqDTO requestParam) {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    couponTaskService.createCouponTask(requestParam);</span></span>
<span class="line"><span>    return Results.success();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这里几个注解的职责并不相同：</p><table tabindex="0"><thead><tr><th>注解</th><th>所属功能</th><th>作用</th></tr></thead><tbody><tr><td><code>@Operation</code></td><td>OpenAPI</td><td>描述接口用途</td></tr><tr><td><code>@NoDuplicateSubmit</code></td><td>项目自定义 AOP</td><td>防止短时间内重复提交</td></tr><tr><td><code>@PostMapping</code></td><td>Spring MVC</td><td>注册 POST 接口映射</td></tr><tr><td><code>@RequestBody</code></td><td>Spring MVC</td><td>将请求体反序列化为 Java 对象</td></tr></tbody></table><p>这几个注解放在一起，并不意味着它们都属于 Swagger。</p><p>尤其是 <code>@NoDuplicateSubmit</code>，它是项目自己的业务增强逻辑，不负责生成接口文档。</p><h3 id="实际测试流程" tabindex="-1">实际测试流程 <a class="header-anchor" href="#实际测试流程" aria-label="Permalink to &quot;实际测试流程&quot;">​</a></h3><ol><li>启动 merchant-admin 服务。</li><li>访问 <code>/v3/api-docs</code>，检查 OpenAPI JSON 是否正常生成。</li><li>访问 <code>/doc.html</code>，查看优惠券模板管理和推送任务管理接口。</li><li>选择一个 GET 接口，填写查询参数，点击调试。</li><li>选择一个 POST 接口，填写 JSON 请求体，发送请求。</li><li>查看 HTTP 响应、业务状态码和返回数据。</li></ol><p>我们项目的本地测试环境已经通过 <code>UserConfiguration</code> 注入了模拟用户，因此当前测试不需要手动添加登录 Token。具体以当前本地环境配置为准。</p><h2 id="八、需要注意的几个问题" tabindex="-1">八、需要注意的几个问题 <a class="header-anchor" href="#八、需要注意的几个问题" aria-label="Permalink to &quot;八、需要注意的几个问题&quot;">​</a></h2><p><strong>1. 接口文档不等于接口实现。</strong></p><p><code>@Operation</code> 只负责补充接口描述，不会改变业务逻辑。</p><p>真正决定接口如何执行的仍然是 Spring MVC 映射和 Controller 中的代码。</p><p><strong>2. 接口文档不一定完全准确。</strong></p><p>如果 DTO 字段说明、必填约束或响应注解没有正确维护，生成的文档也可能与真实业务行为不一致。</p><p>因此需要开发人员维护注解，并通过实际接口测试验证。</p><p><strong>3. 不能把文档调试页面直接暴露在生产环境。</strong></p><p>接口文档可能暴露系统接口路径、参数结构和业务信息。生产环境应根据实际需要关闭文档或者实施访问控制。</p><h2 id="九、总结" tabindex="-1">九、总结 <a class="header-anchor" href="#九、总结" aria-label="Permalink to &quot;九、总结&quot;">​</a></h2><p>通过这次学习，我们需要建立以下认识：</p><ul><li>OpenAPI：描述 HTTP API 的规范。</li><li>Swagger：围绕 API 描述规范的一套工具生态。</li><li>Swagger UI：展示和调试 OpenAPI 文档。</li><li>Springdoc-OpenAPI：扫描 Spring Boot 应用并生成 OpenAPI 描述。</li><li>Knife4j：增强接口文档展示和调试体验。</li></ul><p>它们共同解决的是一个问题：<strong>如何让后端开发的接口能够被其他开发人员、测试人员以及第三方工具准确理解和使用。</strong></p><p>在日常 Java 后端开发中，我们需要熟悉 Spring MVC 注解、OpenAPI 常用注解，以及如何使用 Knife4j 调试接口。这样在接手一个陌生项目时，就可以先通过接口文档了解系统提供了哪些业务能力，再沿着 Controller、Service、Mapper 的调用链深入阅读源码。</p>`,138)])])}const g=s(i,[["render",t]]);export{u as __pageData,g as default};
